package auth

import (
	"fmt"
	"strings"
)

const (
	BedrockAuthStatePresent = "present"
	BedrockAuthStateMissing = "missing"

	BedrockAuthStatusCredentialsMissing = "bedrock_credentials_missing"
	BedrockAuthStatusBearerSelected     = "bedrock_bearer_selected"
	BedrockAuthStatusProfileSelected    = "bedrock_profile_selected"
	BedrockAuthStatusStaticKeySelected  = "bedrock_static_key_selected"
	BedrockAuthStatusSigV4Unavailable   = "bedrock_sigv4_unavailable"
)

type BedrockAuthEvidence struct {
	Source string
	State  string
	Status string
}

func (e BedrockAuthEvidence) String() string {
	return fmt.Sprintf("bedrock auth source=%s state=%s status=%s", e.Source, e.State, e.Status)
}

func (e BedrockAuthEvidence) Error() string {
	return e.String()
}

func ResolveBedrockAuth(env map[string]string) BedrockAuthEvidence {
	if strings.TrimSpace(env["AWS_BEARER_TOKEN_BEDROCK"]) != "" {
		return BedrockAuthEvidence{
			Source: "AWS_BEARER_TOKEN_BEDROCK",
			State:  BedrockAuthStatePresent,
			Status: BedrockAuthStatusBearerSelected,
		}
	}
	accessKey := strings.TrimSpace(env["AWS_ACCESS_KEY_ID"])
	secretKey := strings.TrimSpace(env["AWS_SECRET_ACCESS_KEY"])
	if accessKey != "" && secretKey != "" {
		return BedrockAuthEvidence{
			Source: "AWS_ACCESS_KEY_ID",
			State:  BedrockAuthStatePresent,
			Status: BedrockAuthStatusStaticKeySelected,
		}
	}
	if accessKey != "" || secretKey != "" {
		return BedrockAuthEvidence{
			Source: "AWS_ACCESS_KEY_ID",
			State:  BedrockAuthStateMissing,
			Status: BedrockAuthStatusCredentialsMissing,
		}
	}
	if strings.TrimSpace(env["AWS_PROFILE"]) != "" {
		return BedrockAuthEvidence{
			Source: "AWS_PROFILE",
			State:  BedrockAuthStatePresent,
			Status: BedrockAuthStatusProfileSelected,
		}
	}
	if strings.TrimSpace(env["AWS_CONTAINER_CREDENTIALS_RELATIVE_URI"]) != "" {
		return BedrockAuthEvidence{
			Source: "AWS_CONTAINER_CREDENTIALS_RELATIVE_URI",
			State:  BedrockAuthStatePresent,
			Status: BedrockAuthStatusSigV4Unavailable,
		}
	}
	if strings.TrimSpace(env["AWS_WEB_IDENTITY_TOKEN_FILE"]) != "" {
		return BedrockAuthEvidence{
			Source: "AWS_WEB_IDENTITY_TOKEN_FILE",
			State:  BedrockAuthStatePresent,
			Status: BedrockAuthStatusSigV4Unavailable,
		}
	}
	return BedrockAuthEvidence{State: BedrockAuthStateMissing, Status: BedrockAuthStatusCredentialsMissing}
}

func ResolveBedrockRegion(env map[string]string) string {
	if region := strings.TrimSpace(env["AWS_REGION"]); region != "" {
		return region
	}
	if region := strings.TrimSpace(env["AWS_DEFAULT_REGION"]); region != "" {
		return region
	}
	return "us-east-1"
}

package runtime

import (
	"context"
	"errors"
	"sync"

	"github.com/TrebuchetDynamics/gormes-agent/internal/llm/bedrock/stale"
)

var ErrBedrockRuntimeClientMissing = errors.New("bedrock runtime client missing")

type BedrockRuntimeRequest struct {
	Model string
}

type BedrockRuntimeResponse struct{}

type BedrockRuntimeStreamResponse struct{}

type BedrockRuntimeClient interface {
	Converse(context.Context, BedrockRuntimeRequest) (BedrockRuntimeResponse, error)
	ConverseStream(context.Context, BedrockRuntimeRequest) (BedrockRuntimeStreamResponse, error)
}

type BedrockRuntimeClientFactory func(region string) (BedrockRuntimeClient, error)

type BedrockRuntimeCache struct {
	mu        sync.Mutex
	clients   map[string]BedrockRuntimeClient
	newClient BedrockRuntimeClientFactory
}

func NewBedrockRuntimeCache(newClient BedrockRuntimeClientFactory) *BedrockRuntimeCache {
	return &BedrockRuntimeCache{
		clients:   make(map[string]BedrockRuntimeClient),
		newClient: newClient,
	}
}

func (c *BedrockRuntimeCache) Put(region string, client BedrockRuntimeClient) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.clients[region] = client
}

func (c *BedrockRuntimeCache) Get(region string) (BedrockRuntimeClient, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	client, ok := c.clients[region]
	return client, ok
}

func (c *BedrockRuntimeCache) InvalidateRuntimeClient(region string) bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	_, ok := c.clients[region]
	delete(c.clients, region)
	return ok
}

func (c *BedrockRuntimeCache) EvictOnStaleError(region string, err error) bool {
	if !stale.ClassifyBedrockStaleError(err).Stale {
		return false
	}
	return c.InvalidateRuntimeClient(region)
}

func (c *BedrockRuntimeCache) Converse(ctx context.Context, region string, req BedrockRuntimeRequest) (BedrockRuntimeResponse, error) {
	client, err := c.runtimeClient(region)
	if err != nil {
		return BedrockRuntimeResponse{}, err
	}
	out, err := client.Converse(ctx, req)
	if err != nil {
		c.EvictOnStaleError(region, err)
	}
	return out, err
}

func (c *BedrockRuntimeCache) ConverseStream(ctx context.Context, region string, req BedrockRuntimeRequest) (BedrockRuntimeStreamResponse, error) {
	client, err := c.runtimeClient(region)
	if err != nil {
		return BedrockRuntimeStreamResponse{}, err
	}
	out, err := client.ConverseStream(ctx, req)
	if err != nil {
		c.EvictOnStaleError(region, err)
	}
	return out, err
}

func (c *BedrockRuntimeCache) runtimeClient(region string) (BedrockRuntimeClient, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if client, ok := c.clients[region]; ok {
		return client, nil
	}
	if c.newClient == nil {
		return nil, ErrBedrockRuntimeClientMissing
	}
	client, err := c.newClient(region)
	if err != nil {
		return nil, err
	}
	c.clients[region] = client
	return client, nil
}

package sigv4

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strings"
	"time"
)

type StaticAWSCredentials struct {
	AccessKeyID     string
	SecretAccessKey string
	SessionToken    string
	Region          string
}

func SignBedrockRequest(req *http.Request, creds StaticAWSCredentials, now time.Time) error {
	if req == nil {
		return errors.New("bedrock sigv4 request is nil")
	}
	accessKey := strings.TrimSpace(creds.AccessKeyID)
	secretKey := strings.TrimSpace(creds.SecretAccessKey)
	if accessKey == "" || secretKey == "" {
		return errors.New("bedrock sigv4 static credentials are incomplete")
	}
	region := strings.TrimSpace(creds.Region)
	if region == "" {
		region = bedrockRegionFromHost(req.URL.Host)
	}
	if region == "" {
		region = "us-east-1"
	}

	body, err := bedrockRequestBody(req)
	if err != nil {
		return err
	}
	payloadHash := bedrockSHA256Hex(body)
	amzDate := now.UTC().Format("20060102T150405Z")
	date := now.UTC().Format("20060102")

	req.Header.Set("X-Amz-Date", amzDate)
	req.Header.Set("X-Amz-Content-Sha256", payloadHash)
	if token := strings.TrimSpace(creds.SessionToken); token != "" {
		req.Header.Set("X-Amz-Security-Token", token)
	}

	scope := strings.Join([]string{date, region, "bedrock", "aws4_request"}, "/")
	canonicalRequest, signedHeaders := bedrockCanonicalRequest(req, payloadHash)
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		scope,
		bedrockSHA256Hex([]byte(canonicalRequest)),
	}, "\n")
	signingKey := bedrockSigningKey(secretKey, date, region, "bedrock")
	signature := hex.EncodeToString(bedrockHMAC(signingKey, stringToSign))
	req.Header.Set("Authorization", fmt.Sprintf(
		"AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		accessKey,
		scope,
		signedHeaders,
		signature,
	))
	return nil
}

func bedrockRequestBody(req *http.Request) ([]byte, error) {
	if req.Body == nil {
		return nil, nil
	}
	body, err := io.ReadAll(req.Body)
	if err != nil {
		return nil, errors.New("bedrock sigv4 request body could not be read")
	}
	req.Body = io.NopCloser(bytes.NewReader(body))
	req.ContentLength = int64(len(body))
	return body, nil
}

func bedrockCanonicalRequest(req *http.Request, payloadHash string) (string, string) {
	signedHeaders := []string{"host", "x-amz-content-sha256", "x-amz-date"}
	if req.Header.Get("X-Amz-Security-Token") != "" {
		signedHeaders = append(signedHeaders, "x-amz-security-token")
	}
	sort.Strings(signedHeaders)

	headerValues := map[string]string{
		"host":                 bedrockCanonicalHost(req),
		"x-amz-content-sha256": payloadHash,
		"x-amz-date":           req.Header.Get("X-Amz-Date"),
	}
	if token := req.Header.Get("X-Amz-Security-Token"); token != "" {
		headerValues["x-amz-security-token"] = token
	}

	var canonicalHeaders strings.Builder
	for _, name := range signedHeaders {
		canonicalHeaders.WriteString(name)
		canonicalHeaders.WriteByte(':')
		canonicalHeaders.WriteString(strings.Join(strings.Fields(headerValues[name]), " "))
		canonicalHeaders.WriteByte('\n')
	}
	signedHeadersText := strings.Join(signedHeaders, ";")
	return strings.Join([]string{
		req.Method,
		bedrockCanonicalURI(req.URL),
		bedrockCanonicalQuery(req.URL),
		canonicalHeaders.String(),
		signedHeadersText,
		payloadHash,
	}, "\n"), signedHeadersText
}

func bedrockCanonicalHost(req *http.Request) string {
	if req.Host != "" {
		return req.Host
	}
	if req.URL != nil {
		return req.URL.Host
	}
	return ""
}

func bedrockCanonicalURI(u *url.URL) string {
	if u == nil {
		return "/"
	}
	path := u.EscapedPath()
	if path == "" {
		return "/"
	}
	return path
}

func bedrockCanonicalQuery(u *url.URL) string {
	if u == nil || u.RawQuery == "" {
		return ""
	}
	values := u.Query()
	pairs := make([]string, 0)
	for key, rawValues := range values {
		sort.Strings(rawValues)
		for _, value := range rawValues {
			pairs = append(pairs, bedrockURIEncode(key)+"="+bedrockURIEncode(value))
		}
	}
	sort.Strings(pairs)
	return strings.Join(pairs, "&")
}

func bedrockURIEncode(value string) string {
	escaped := url.QueryEscape(value)
	escaped = strings.ReplaceAll(escaped, "+", "%20")
	return strings.ReplaceAll(escaped, "%7E", "~")
}

func bedrockSHA256Hex(body []byte) string {
	sum := sha256.Sum256(body)
	return hex.EncodeToString(sum[:])
}

func bedrockSigningKey(secret, date, region, service string) []byte {
	kDate := bedrockHMAC([]byte("AWS4"+secret), date)
	kRegion := bedrockHMAC(kDate, region)
	kService := bedrockHMAC(kRegion, service)
	return bedrockHMAC(kService, "aws4_request")
}

func bedrockHMAC(key []byte, data string) []byte {
	mac := hmac.New(sha256.New, key)
	_, _ = mac.Write([]byte(data))
	return mac.Sum(nil)
}

func bedrockRegionFromHost(host string) string {
	parts := strings.Split(host, ".")
	if len(parts) >= 3 && parts[0] == "bedrock-runtime" {
		return parts[1]
	}
	return ""
}

package stale

import (
	"errors"
	"strings"
)

const (
	BedrockStaleTransportStatus      = "bedrock_stale_transport"
	BedrockNonRetryableRequestStatus = "bedrock_non_retryable_request_failure"
)

var (
	ErrBedrockConnectionClosed = errors.New("connection closed")
	ErrBedrockProtocolError    = errors.New("protocol error")
	ErrBedrockReadTimeout      = errors.New("read timeout")
	ErrBedrockUnexpectedEOF    = errors.New("unexpected EOF")
)

type BedrockRuntimeErrorKind string

const (
	BedrockRuntimeErrorAssertion          BedrockRuntimeErrorKind = "assertion"
	BedrockRuntimeErrorValidation         BedrockRuntimeErrorKind = "validation"
	BedrockRuntimeErrorAuth               BedrockRuntimeErrorKind = "auth"
	BedrockRuntimeErrorMissingCredentials BedrockRuntimeErrorKind = "missing_credentials"
	BedrockRuntimeErrorMalformedRequest   BedrockRuntimeErrorKind = "malformed_request"
)

type BedrockRuntimeError struct {
	Kind          BedrockRuntimeErrorKind
	Message       string
	SourcePackage string
}

func (e BedrockRuntimeError) Error() string {
	if e.Message != "" {
		return e.Message
	}
	return string(e.Kind)
}

type BedrockStaleErrorClassification struct {
	Stale  bool
	Status string
}

func ClassifyBedrockStaleError(err error) BedrockStaleErrorClassification {
	if err == nil {
		return BedrockStaleErrorClassification{}
	}
	if errors.Is(err, ErrBedrockConnectionClosed) ||
		errors.Is(err, ErrBedrockProtocolError) ||
		errors.Is(err, ErrBedrockReadTimeout) ||
		errors.Is(err, ErrBedrockUnexpectedEOF) {
		return bedrockStaleTransportClassification()
	}
	var runtimeErr BedrockRuntimeError
	if errors.As(err, &runtimeErr) &&
		runtimeErr.Kind == BedrockRuntimeErrorAssertion &&
		bedrockStaleLibrarySource(runtimeErr.SourcePackage) {
		return bedrockStaleTransportClassification()
	}
	if errors.As(err, &runtimeErr) && bedrockNonRetryableRequestError(runtimeErr.Kind) {
		return BedrockStaleErrorClassification{
			Status: BedrockNonRetryableRequestStatus,
		}
	}
	return BedrockStaleErrorClassification{}
}

func bedrockStaleTransportClassification() BedrockStaleErrorClassification {
	return BedrockStaleErrorClassification{
		Stale:  true,
		Status: BedrockStaleTransportStatus,
	}
}

func bedrockStaleLibrarySource(sourcePackage string) bool {
	return strings.HasPrefix(sourcePackage, "urllib3.") ||
		strings.HasPrefix(sourcePackage, "botocore.") ||
		strings.HasPrefix(sourcePackage, "boto3.")
}

func bedrockNonRetryableRequestError(kind BedrockRuntimeErrorKind) bool {
	switch kind {
	case BedrockRuntimeErrorValidation,
		BedrockRuntimeErrorAuth,
		BedrockRuntimeErrorMissingCredentials,
		BedrockRuntimeErrorMalformedRequest:
		return true
	default:
		return false
	}
}

